// ===== Termo de Aceite (resposta do formulário) =====
// Desde 19/11/2026 a inclusão começa pelo Termo de Aceite, e não mais pelo contrato do Contraktor.
// O bolsão e o tipo de pessoa vêm do nome do formulário, ex.:
// "Resposta do formulário _Termo de Aceite Pessoa Física - Rua Exemplo (BASE)_Fulano de Tal.pdf"
const texto = $json.text || '';
const arquivo = $('Pegar ID da Mensagem').item.json.name || '';
const assunto = $('Receber PDF do Contrato').item.json.subject || '';

const semAcento = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const T = semAcento(texto).toUpperCase().replace(/\s+/g, ' ');
const ehTermo = T.includes('TERMO DE SOLICITACAO DE SERVICOS') && T.includes('DADOS DO CLIENTE');

// Bolsão e tipo de pessoa: nome do arquivo e, se preciso, assunto do e-mail
let bolsao = null, tipoPessoa = null;
for (const s of [arquivo, assunto]) {
  const m = semAcento(s).match(/Termo de Aceite\s+Pessoa\s+(Fisica|Juridica)\s*-\s*([^_(]+)/i);
  if (!m) continue;
  tipoPessoa = /^f/i.test(m[1]) ? 'PF' : 'PJ';
  // pega o mesmo trecho no texto original (com acentos)
  const ini = semAcento(s).indexOf(m[2]);
  bolsao = String(s).slice(ini, ini + m[2].length).replace(/\.pdf$/i, '').trim().toUpperCase() || null;
  break;
}

// Documento do cliente: CNPJ (PJ) ou o primeiro CPF do termo (PF)
const soDigitos = s => String(s || '').replace(/\D/g, '');
const cnpj = (texto.match(/CNPJ:?\s*(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2})/i) || [])[1] || null;
const cpf = (texto.match(/CPF:?\s*(\d{3}\.?\d{3}\.?\d{3}-?\d{2})/i) || [])[1] || null;
if (!tipoPessoa) tipoPessoa = cnpj ? 'PJ' : (cpf ? 'PF' : null);
const documento = tipoPessoa === 'PJ' ? (cnpj || cpf) : (cpf || cnpj);

// Datas: início dos serviços e data do aceite ("São Paulo, 18 de outubro de 2026")
const dataInicio = (texto.match(/DATA DE IN[IÍ]CIO:?\s*(\d{2}\/\d{2}\/\d{4})/i) || [])[1] || null;
const MESES = { janeiro: 1, fevereiro: 2, marco: 3, abril: 4, maio: 5, junho: 6, julho: 7, agosto: 8, setembro: 9, outubro: 10, novembro: 11, dezembro: 12 };
let dataAceite = null;
const aceites = [...semAcento(texto).matchAll(/,\s*(\d{1,2})\s+de\s+([a-z]+)\s+de\s+(\d{4})/gi)];
if (aceites.length) {
  const [, d, mes, a] = aceites[aceites.length - 1];
  const m = MESES[mes.toLowerCase()];
  if (m) dataAceite = String(d).padStart(2, '0') + '/' + String(m).padStart(2, '0') + '/' + a;
}

// Chave do termo no Lists (coluna IDContraktor): evita registrar o mesmo cliente duas vezes no mesmo bolsão
const chaveBolsao = semAcento(bolsao).toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');
const chaveTermo = (documento && chaveBolsao) ? 'TERMO-' + soDigitos(documento) + '-' + chaveBolsao : null;

let motivo = null;
if (texto.replace(/\s/g, '').length < 200) motivo = 'O PDF não tem texto legível (foi impresso ou escaneado). Envie o PDF original da resposta do formulário.';
else if (!ehTermo) motivo = 'O PDF não é um Termo de Aceite (resposta do formulário). Desde 19/11/2026 a inclusão começa pelo formulário; contratos do Contraktor não iniciam mais o fluxo.';
else if (!bolsao) motivo = 'Bolsão não identificado. O nome do arquivo deve ser o original do formulário ("Termo de Aceite Pessoa Física/Jurídica - BOLSÃO ...").';
else if (!documento) motivo = 'CPF/CNPJ do cliente não encontrado no Termo de Aceite.';

return {
  json: {
    valido: !motivo,
    motivo,
    chaveTermo,
    bolsao,
    tipoPessoa,
    documento,
    dataInicio,
    dataAceite,
    arquivo,
    tituloDocumento: arquivo.replace(/^Resposta do formul[aá]rio\s*_?/i, '').replace(/\.pdf$/i, '').trim() || null,
    textoCompleto: texto
  }
};

