// Lê a resposta estruturada da OpenAI (Responses API) de forma robusta
const resp = $json;
const outputs = Array.isArray(resp.output) ? resp.output : [];
const msg = outputs.find(o => o.type === 'message') || outputs.find(o => Array.isArray(o.content));
const parte = (msg?.content || []).find(c => c.type === 'output_text') || (msg?.content || [])[0];

let dadosIA = parte?.json ?? parte?.text ?? resp.text ?? resp.message?.content ?? null;

if (typeof dadosIA === 'string') {
  try {
    dadosIA = JSON.parse(dadosIA);
  } catch (e) {
    throw new Error('A resposta da IA não é um JSON válido: ' + dadosIA.slice(0, 300));
  }
}

if (!dadosIA || typeof dadosIA !== 'object') {
  throw new Error('Não foi possível localizar os dados estruturados retornados pela IA.');
}

const termo = $('Extrair Dados do Termo').item.json;

// ---------- 1. Remove qualquer valor monetário que a IA tenha deixado passar ----------
const semValores = s => String(s)
  .replace(/\s*[-–—:,]?\s*(valor\s+(mensal|total)?\s*(de\s+)?)?R\$\s*[\d.]+(,\d{1,2})?(\s*\([^)]*\))?(\s*mensa(l|is))?/gi, '')
  .replace(/\(\s*(?:ou|e|,|\/|\s)*\)/gi, '')
  .replace(/\s{2,}/g, ' ')
  .replace(/[\s;,–—-]+$/, '')
  .trim();

const limpar = v => {
  if (typeof v === 'string') return semValores(v) || null;
  if (Array.isArray(v)) return v.map(limpar).filter(x => x !== null && x !== '');
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, limpar(x)]));
  return v;
};
dadosIA = limpar(dadosIA);

// ---------- 2. Contratante: nunca e-mails/nomes internos da ASTER ----------
const DOMINIOS_INTERNOS = ['@suaempresa.com.br', '@empresa-do-grupo.com.br'];
const interno = e => DOMINIOS_INTERNOS.some(d => String(e || '').toLowerCase().endsWith(d));
const contratantes = (dadosIA.contratantes || [])
  .filter(c => !/\baster\b/i.test(c.nomeRazaoSocial || ''))
  .map(c => ({
    ...c,
    tipoPessoa: termo.tipoPessoa || c.tipoPessoa,
    cpfCnpj: c.cpfCnpj || termo.documento || null,
    email: interno(c.email) ? null : (c.email || null)
  }));

// ---------- 3. Pontos de atenção ----------
const pontosAtencao = (dadosIA.pontosAtencao || []).filter(Boolean).slice(0, 5);
if (!contratantes.length) pontosAtencao.push('Nenhum cliente identificado no Termo de Aceite.');

// Termo de Aceite válido = sempre adesão de um novo cliente ao bolsão do formulário
const bolsao = termo.bolsao || dadosIA.bolsao || null;
const nome = (contratantes[0] || {}).nomeRazaoSocial;

return {
  json: {
    chaveTermo: termo.chaveTermo,
    tituloDocumento: termo.tituloDocumento,
    dataAssinatura: termo.dataAceite,

    ...dadosIA,

    tipoAdesao: 'Bolsão',
    adesaoBolsao: true,
    tipoMovimento: 'Novo Cliente',
    tipoDocumento: 'Termo de Aceite – ' + (termo.tipoPessoa === 'PJ' ? 'Pessoa Jurídica' : 'Pessoa Física'),
    bolsao,
    identificacaoCliente: [bolsao, nome].filter(Boolean).join(' - ') || null,
    dataInicioContrato: termo.dataInicio || dadosIA.dataInicioContrato || null,
    dataInicioServicoMensal: termo.dataInicio || dadosIA.dataInicioServicoMensal || null,
    contratantes,
    contratadas: [],
    contratada: { razaoSocial: null, cnpj: null, endereco: null },
    empresaAster: null,
    cnpjAster: null,
    pontosAtencao
  }
};

const d = $('Organizar Dados da Inclusão').item.json;

// Converte DD/MM/AAAA (ou D/M/AAAA) para YYYY-MM-DD
function dataSharePoint(data) {
  if (!data) return null;
  const partes = String(data).trim().split('/');
  if (partes.length !== 3) return null;
  const [dia, mes, ano] = partes;
  if (!/^\d{4}$/.test(ano)) return null;
  return `${ano}-${mes.padStart(2, '0')}-${dia.padStart(2, '0')}`;
}

// Somente estes movimentos seguem para o fluxo de inclusão (Financeiro/Cadastros/Comercial/Operacional)
const MOVIMENTOS_INCLUSAO = ['Novo Cliente', 'Inclusão de Cliente'];
const segueInclusao = MOVIMENTOS_INCLUSAO.includes(d.tipoMovimento);

// Colunas do cliente (uma linha por cliente, na mesma ordem): Cliente = só o nome; Telefone; Email; Rua; Numero
const lista = (d.contratantes || []).filter(c => c.nomeRazaoSocial);
const coluna = campo => { const v = lista.map(c => String(campo(c) || '').trim()); return v.some(Boolean) ? v.join('\n') : null; };
const cliente = coluna(c => c.nomeRazaoSocial);
const telefone = coluna(c => c.telefone);
const email = coluna(c => c.email);
const rua = coluna(c => c.rua || (c.numero ? null : c.endereco));
const numero = coluna(c => c.numero);

// Empresa(s) ASTER com CNPJ
const empresaAster = (d.contratadas || [])
  .map(c => `${c.razaoSocial}${c.cnpj ? ` (CNPJ ${c.cnpj})` : ''}`)
  .join(' / ') || d.empresaAster || null;

const locais = (d.locaisInstalacao || []).join('\n');

const servicos = (d.servicos || [])
  .map(s => {
    const quantidade = s.quantidade ? `${s.quantidade}x ` : '';
    return `${quantidade}${s.descricao || ''}`;
  })
  .join('\n');

// Condições do termo resumidas em um único campo
const condicoes = [
  ['Início do contrato', d.dataInicioContrato || d.regraInicioContrato],
  ['Início dos serviços', d.dataInicioServicoMensal || d.regraInicioServicoMensal],
  ['Início da cobrança', d.dataInicioCobrancaMensal || d.regraInicioCobrancaMensal],
  ['Vigência mínima', d.vigenciaMinimaMeses ? `${d.vigenciaMinimaMeses} meses` : null],
  ['Aviso prévio', d.avisoPrevioDias ? `${d.avisoPrevioDias} dias` : null],
  ['Término', d.dataFim]
].filter(([, v]) => v).map(([k, v]) => `${k}: ${v}`).join('\n');

return {
  json: {
    // No Lists: coluna "Bolsão" (interna Title) = bolsão | coluna "Cliente" = um cliente por linha
    Title: d.bolsao || d.identificacaoCliente || d.tituloDocumento || 'Bolsão não identificado',
    Cliente: cliente,
    Telefone: telefone,
    Email: email,
    Rua: rua,
    Numero: numero,

    // Coluna IDContraktor guarda a chave do Termo de Aceite (TERMO-<CPF/CNPJ>-<BOLSÃO>)
    IDContraktor: d.chaveTermo ?? null,
    StatusAutomacao: segueInclusao ? 'Aguardando Financeiro e Cadastros' : 'Revisão Manual',
    TipoMovimento: d.tipoMovimento ?? null,
    DataAssinatura: dataSharePoint(d.dataAssinatura),

    EmpresaAster: empresaAster,
    NumeroProposta: d.numeroProposta ?? null,
    CondicoesContrato: condicoes || null,

    LocaisInstalacao: locais,
    ServicosContratados: servicos,

    FinanceiroStatus: 'Aguardando Cadastro',
    CadastrosStatus: 'Aguardando Cadastros',
    ComercialStatus: 'Aguardando Comercial',
    OperacionalStatus: 'Aguardando Operacional'
  }
};

const d = $('Organizar Dados da Inclusão').item.json;

const contratantes = d.contratantes || [];

const findme = contratantes.map((c, i) => ({
  morador: i + 1,
  bolsao: d.bolsao ?? d.identificacaoCliente ?? null,
  rua: c.rua ?? null,
  numero: c.numero ?? null
}));

const monuv = contratantes.map((c, i) => ({
  morador: i + 1,
  nome: c.nomeRazaoSocial ?? null,
  telefone: c.telefone ?? null,
  email: c.email ?? null
}));

const sigma = contratantes.map((c, i) => ({
  morador: i + 1,
  nome: c.nomeRazaoSocial ?? null,
  rua: c.rua ?? null,
  numero: c.numero ?? null
}));

return {
  json: {
    itemId: $('Create item in a list').item.json.id,
    cliente: d.identificacaoCliente ?? null,
    dataReferencia: d.dataAssinatura ?? null,
    bolsao: d.bolsao ?? d.identificacaoCliente ?? null,
    pontosAtencao: d.pontosAtencao || [],

    findme,
    monuv,
    sigma
  }
};

const d = $('Preparar Dados Cadastros').item.json;
const org = $('Organizar Dados da Inclusão').item.json;

// Um bloco por cliente, com tudo o que os três sistemas precisam (sem repetir)
const clientes = (org.contratantes || []).map(c => {
  const endereco = [c.rua, c.numero].filter(Boolean).join(' ') || c.endereco || 'Não informado';
  return `👤 *Cliente:* ${c.nomeRazaoSocial || 'Não informado'}
📍 *Endereço:* ${endereco}
📞 *Telefone:* ${c.telefone || 'Não informado'}
📧 *E-mail:* ${c.email || 'Não informado'}`;
}).join('\n\n') || '👤 *Cliente:* Não informado';

const mensagem = `🆕 *INCLUSÃO DE CLIENTE – CADASTROS*

🏘️ *Bolsão:* ${d.bolsao || 'Não informado'}

${clientes}

📌 *Ação necessária:*
Cadastrar no FINDME, MONUV e SIGMA.

Após concluir, selecione uma opção abaixo.`;

return [{
  json: {
    itemId: d.itemId,
    cliente: d.cliente,
    dataReferencia: d.dataReferencia,
    mensagem
  }
}];

